@startuml

class Factory {
}

class Machine {
  + SerialNumber : string
  + Make : string
  + Model : string
  + PurchaseDate : date
}

class Worker {
  + FirstName : string
  + LastName : string
  + BirthDate : date
  + Address : string
  + Skills : string[]
}

class ProductType {
  + ProductTypeId : string
  + Weight : float
}

class Material {
  + MaterialId : string
  + Name : string
}

class Client {
  + ClientId : string
  + Name : string
  + Address : string
  + PhoneNumber : string
  + ContactPerson : string
}

class PurchaseOrder {
  + OrderNumber : string
  + OrderDate : date
  + ExpectedDeliveryDate : date
  + ActualDeliveryDate : date
}

class OrderLine {
  + Quantity : int
}

Factory "1" -- "*" Machine
Machine "1" -- "*" Worker
Machine "1" -- "*" ProductType
ProductType "*" -- "1" Material
Client "1" -- "*" PurchaseOrder
PurchaseOrder "1" *-- "*" OrderLine
OrderLine "*" -- "1" ProductType

@enduml

